public static class FrameGeneration {
 public static string Configure(string text,DlssOptions o){string mode=o.FrameMode??"keep";if(!new[]{"keep","off","opti","native"}.Contains(mode)||o.FrameMultiplier<2||o.FrameMultiplier>6)throw new Exception("Scelta Frame Generation non valida.");if(mode=="keep")return text;if(o.AdaMfg&&(mode!="native"||o.Build!="y4my4my4m"))throw new Exception("MFG RTX 4000 sperimentale richiede la build y4my4my4m e FG del gioco.");text=Core.Set(text,"FrameGen","Enabled",mode=="opti"?"true":"false");text=Core.Set(text,"FrameGen","FGInput",mode=="opti"?"upscaler":"nofg");text=Core.Set(text,"FrameGen","FGOutput",mode=="opti"?"dlssg":"nofg");if(Core.Get(text,"FrameGen","External")!=null)text=Core.Set(text,"FrameGen","External","false");text=Core.Set(text,"FrameGen","FGNvngxReplacement","None");text=Core.Set(text,"DLSSG","InterpolationCount",mode=="opti"?(o.FrameMultiplier-1).ToString():"auto");text=Core.Set(text,"DLSSG","OverrideInterpolationCount",mode=="native"?(o.FrameMultiplier-1).ToString():"auto");text=Core.Set(text,"DLSSG","ForceDMFG","false");text=Core.Set(text,"DLSSG","OverrideForceDMFG","false");if(o.Build=="y4my4my4m"||Core.Get(text,"DLSSG","AdaMfgUnlock")!=null)text=Core.Set(text,"DLSSG","AdaMfgUnlock",o.AdaMfg&&mode=="native"?"true":"false");return text;}
 public static void ValidateChoice(DlssOptions o,int series){if(o.FrameMode=="keep"||o.FrameMode=="off"||o.FrameMode==null)return;if(series!=40&&series!=50)throw new Exception("GPU RTX 4000/5000 non rilevata: impossibile verificare Frame Generation.");if(o.AdaMfg&&series!=40)throw new Exception("Lo sblocco Ada è riservato a RTX 4000.");if(series==40&&o.FrameMultiplier>2&&!(o.AdaMfg&&o.FrameMode=="native"&&o.Build=="y4my4my4m"))throw new Exception("RTX 4000: DLSS FG standard supporta 2×. Per MFG del gioco serve lo sblocco sperimentale y4my4my4m.");}
 public static void Validate(Game g,DlssOptions o,string package){if(o.FrameMode==null||o.FrameMode=="keep"||o.FrameMode=="off")return;ValidateChoice(o,DlssHardware.Detect().Series);string root=Path.GetDirectoryName(g.Exe);if(InjectionSetup.Profile(g).Api=="dx11"||InjectionSetup.Profile(g).Api=="vulkan")throw new Exception("Questi controlli FG sono previsti per DirectX 12. I ponti DX11/Vulkan richiedono verifica separata.");var dirs=new[]{root,Path.Combine(root,"OptiScaler"),Path.Combine(root,"OptiScaler","streamline")};string[] needed=o.FrameMode=="opti"?new[]{"sl.interposer.dll","sl.common.dll","sl.dlss_g.dll","sl.reflex.dll","sl.pcl.dll","nvngx_dlssg.dll"}:new[]{"sl.interposer.dll","sl.dlss_g.dll","nvngx_dlssg.dll"};foreach(string name in needed)if(!dirs.Any(d=>DlssCore.Pe64(Path.Combine(d,name))))throw new Exception("Componente FG non trovato: "+name+". Occorre uno stack Streamline/FG compatibile già installato. Nessuna DLL del gioco viene sostituita automaticamente.");if(o.FrameMode=="native"){var interposer=dirs.Select(d=>Path.Combine(d,"sl.interposer.dll")).First(File.Exists);var v=FileVersionInfo.GetVersionInfo(interposer);if(v.FileMajorPart<2||(v.FileMajorPart==2&&(v.FileMinorPart<7||(v.FileMinorPart==7&&v.FileBuildPart<1))))throw new Exception("Il moltiplicatore del gioco richiede Streamline 2.7.1 o successivo.");}if(o.AdaMfg){string ini=package==null?Path.Combine(root,"OptiScaler.ini"):Path.Combine(package,"OptiScaler.ini");if(!File.Exists(ini)||Core.Get(File.ReadAllText(ini),"DLSSG","AdaMfgUnlock")==null)throw new Exception("Questa installazione non dichiara AdaMfgUnlock. Aggiorna prima la build y4my4my4m.");}}
}
