public static class DlssCore {
 public const string Marker="hdr-unlock-dlss.json";
 public static readonly string[] Proxies={"dxgi.dll","winmm.dll","version.dll","dbghelp.dll","d3d12.dll","wininet.dll","winhttp.dll"};
 static readonly string[] BackupSuffixes={".dlss5-autopilot-backup",".dlss5kur-yedek",".dlss5-installer-backup"};
 public static string Hash(string file){using(var s=File.OpenRead(file))using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(s)).Replace("-","").ToLowerInvariant();}
 static string BytesHash(byte[] data){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(data)).Replace("-","").ToLowerInvariant();}
 public static string Safe(string root,string relative){
  if(String.IsNullOrWhiteSpace(relative)||Path.IsPathRooted(relative)||relative.IndexOf(':')>=0||relative.IndexOf('\0')>=0)throw new Exception("Percorso del pacchetto non valido.");
  var parts=relative.Replace('\\','/').Split('/');if(parts.Any(x=>x==".."||x=="."||x.TrimEnd(' ','.')!=x||Regex.IsMatch(x,@"^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(\.|$)",RegexOptions.IgnoreCase)))throw new Exception("Percorso non sicuro: "+relative);
  string top=Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar,path=Path.GetFullPath(Path.Combine(top,relative.Replace('/',Path.DirectorySeparatorChar)));
  if(!path.StartsWith(top,StringComparison.OrdinalIgnoreCase))throw new Exception("Percorso fuori dalla cartella.");
  string cursor=path;while(cursor!=null){if((File.Exists(cursor)||Directory.Exists(cursor))&&(File.GetAttributes(cursor)&FileAttributes.ReparsePoint)!=0)throw new Exception("Collegamento filesystem non supportato: "+cursor);if(String.Equals(cursor.TrimEnd('\\'),top.TrimEnd('\\'),StringComparison.OrdinalIgnoreCase))break;cursor=Path.GetDirectoryName(cursor);}return path;
 }
 public static bool Pe64(string file){try{using(var r=new BinaryReader(File.OpenRead(file))){if(r.ReadUInt16()!=0x5a4d)return false;r.BaseStream.Position=60;int offset=r.ReadInt32();if(offset<64||offset>r.BaseStream.Length-6)return false;r.BaseStream.Position=offset;return r.ReadUInt32()==0x4550&&r.ReadUInt16()==0x8664;}}catch{return false;}}
 public static bool IsOpti(string file){if(!File.Exists(file))return false;try{var v=FileVersionInfo.GetVersionInfo(file);if(((v.ProductName??"")+" "+(v.FileDescription??"")).IndexOf("OptiScaler",StringComparison.OrdinalIgnoreCase)>=0)return true;
 if(new FileInfo(file).Length>80000000)return false;byte[] bytes=File.ReadAllBytes(file);string t=Encoding.ASCII.GetString(bytes);return Pe64(file)&&t.Contains("OptiScaler.ini")&&t.Contains("OptiScaler");}catch{return false;}}
 // This exact DLSS 5 Swapper UI overlay is not the separate RenoDX NR renderer.
 // Source: rakanki911/DLSS5-Swapper overlay/README.md and overlay/overlay.cpp.
 // Never exempt arbitrary files merely because their name includes "overlay".
 static bool KnownControlOverlay(string file){
  if(!Regex.IsMatch(Path.GetFileName(file),@"^dlss5-lab-overlay-[0-9a-f]{16}\.addon64$",RegexOptions.IgnoreCase))return false;
  try{return Pe64(file)&&Hash(file)=="0d90c616cc1b051f7417b823e5de46eca36767fe1f3716ba9571fbddae492631";}catch{return false;}
 }
 public static string ReadIni(string folder){string p=Safe(folder,"OptiScaler.ini");return File.Exists(p)?File.ReadAllText(p):"";}
 public static DlssScan Inspect(Game g,bool checkExecutable=true,bool installingNeuralRendering=true){
  if(String.IsNullOrEmpty(g.Exe)||!File.Exists(g.Exe))throw new Exception("Eseguibile del gioco non trovato.");
  var s=new DlssScan{Folder=Path.GetDirectoryName(Path.GetFullPath(g.Exe))};Safe(s.Folder,Path.GetFileName(g.Exe));s.Ini=ReadIni(s.Folder);s.Runtime=Safe(s.Folder,"nvngx_dlssnr.dll");
  if(checkExecutable&&!XboxLibrary.IsGameX64(g,g.Exe))s.Blockers.Add("Impossibile verificare un eseguibile x64: il file potrebbe essere protetto o non compatibile. Lo scambio delle DLL DLSS 5 verifica separatamente la DLL selezionata.");
  var loaders=Proxies.Where(p=>IsOpti(Safe(s.Folder,p))).ToList();if(loaders.Count>1)s.Blockers.Add("Più loader OptiScaler rilevati: risolvi il doppione prima di installare.");s.Proxy=loaders.FirstOrDefault()??"";
  if(s.Proxy!="")s.Owner="OptiScaler rilevato · provenienza da verificare";
  string own=Safe(s.Folder,Marker),foreign=Safe(s.Folder,"dlss5-autopilot.json");
  if(File.Exists(foreign)){try{var m=Core.Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(foreign));object v;if(m.TryGetValue("path",out v)&&Convert.ToString(v)=="optiscaler"){s.Autopilot=true;s.Owner=s.Proxy!=""?"Neural Rendering installato precedentemente con DLSS 5 Autopilot":"Registro di una precedente installazione con DLSS 5 Autopilot · file da verificare";if(m.TryGetValue("opti_build",out v))s.Build=Convert.ToString(v);s.Notes.Add("Provenienza del registro precedente: DLSS 5 Autopilot. Il registro serve solo a riconoscere i file e i backup già presenti; HDLSS non usa Autopilot per installare.");}else s.Blockers.Add("Altra modalità DLSS Autopilot presente: rimuovila dalla sua app prima di aggiungere OptiScaler.");}catch{s.Blockers.Add("Registro Autopilot non leggibile: nessuna rimozione automatica.");}}
  if(File.Exists(own)){var m=ReadManifest(s.Folder);s.Managed=true;s.Build=m.Build;s.Owner="Gestito da HDLSS · "+m.Release;s.Notes.Add("Ripristino: stato precedente a HDLSS ("+m.PreviousOwner+").");}
  foreach(string p in Proxies){string path=Safe(s.Folder,p);if(File.Exists(path)&&!loaders.Contains(p))s.Notes.Add(p+": componente esistente conservato");}
  if(File.Exists(Safe(s.Folder,"ReShade64.dll")))s.Notes.Add("ReShade64.dll presente: caricamento tramite OptiScaler disponibile.");
  foreach(string p in Directory.GetFiles(s.Folder,"*.addon64")){string n=Path.GetFileName(p);if(installingNeuralRendering&&!KnownControlOverlay(Safe(s.Folder,n))&&(n.IndexOf("dlss",StringComparison.OrdinalIgnoreCase)>=0||n.IndexOf("neural",StringComparison.OrdinalIgnoreCase)>=0))s.Blockers.Add("Altro add-on DLSS 5 rilevato: "+n+". Evita due passaggi NR contemporanei.");else s.Notes.Add("Add-on conservato: "+n);}
  if(Directory.Exists(Safe(g.Root,"EasyAntiCheat"))||Directory.Exists(Safe(g.Root,"BattlEye"))||Directory.GetFiles(s.Folder,"*EasyAntiCheat*").Length>0)s.Blockers.Add("Anti-cheat rilevato: installazione non supportata.");
  s.Notes.Add("La presenza dei file non conferma l’attivazione in gioco.");return s;
 }
 public static DlssManifest ReadManifest(string root,string marker=Marker){var m=Core.Json.Deserialize<DlssManifest>(File.ReadAllText(Safe(root,marker)));if(m==null||m.Schema!=1||m.Files==null||m.Files.Count>2000||!String.Equals(m.Folder,Path.GetFullPath(root),StringComparison.OrdinalIgnoreCase))throw new Exception("Registro HDLSS non valido per questa cartella.");foreach(var f in m.Files){Safe(root,f.Name);if(f.Before!=null)Safe(Core.Data,f.Backup);}return m;}
 public static DlssRelease PickRelease(string json,DlssBuild build){
  var releases=Core.Json.Deserialize<List<Dictionary<string,object>>>(json);foreach(var r in releases.OrderByDescending(r=>r.ContainsKey("published_at")?Convert.ToString(r["published_at"]):"",StringComparer.Ordinal)){if(r.ContainsKey("draft")&&Convert.ToBoolean(r["draft"]))continue;object[] assets=(r["assets"] as System.Collections.ArrayList??new System.Collections.ArrayList((object[])r["assets"])).ToArray();
   var candidates=assets.Cast<Dictionary<string,object>>().Where(a=>{string n=Convert.ToString(a["name"]).ToLowerInvariant();return n.Contains("optiscaler")&&(n.EndsWith(".zip")||n.EndsWith(".7z"))&&!n.Contains("with_dlss")&&!n.Contains("rtx40-mfg")&&!n.Contains("symbols");}).ToList();
   if(candidates.Count==0)continue;var a2=candidates.OrderByDescending(a=>Convert.ToString(a["name"]),StringComparer.OrdinalIgnoreCase).First();string url=Convert.ToString(a2["browser_download_url"]);if(!url.StartsWith("https://github.com/"+build.Repo+"/releases/download/",StringComparison.OrdinalIgnoreCase))throw new Exception("Origine del pacchetto non valida.");return new DlssRelease{Tag=Convert.ToString(r["tag_name"]),Url=url,Asset=Convert.ToString(a2["name"]),Digest=a2.ContainsKey("digest")?Convert.ToString(a2["digest"]):""};
  }throw new Exception("Nessun pacchetto OptiScaler compatibile trovato nelle ultime release.");
 }
 public sealed class DownloadClient:WebClient {
 public new string DownloadString(string url){ActivityLog.Progress("Ricerca delle versioni disponibili…");try{string result=base.DownloadString(url);ActivityLog.Progress("Catalogo aggiornato",100);return result;}catch{ActivityLog.Progress("Download non riuscito",100);throw;}}
 public new void DownloadFile(string url,string path){ActivityLog.Progress("Download del componente…");ActivityLog.Write("Download del componente avviato");try{base.DownloadFile(url,path);ActivityLog.Write("Download completato");ActivityLog.Progress("Download terminato · verifica del pacchetto",100);}catch{ActivityLog.Progress("Download non riuscito",100);throw;}}
protected override WebResponse GetWebResponse(WebRequest request){try{var response=base.GetWebResponse(request);ActivityLog.Write("Connessione riuscita: "+request.RequestUri.Host);return response;}catch(Exception ex){ActivityLog.Write("Errore download: "+ex.Message);throw;}}protected override WebRequest GetWebRequest(Uri address){ActivityLog.Write("Download / verifica: "+address.ToString());var req=base.GetWebRequest(address);req.CachePolicy=new System.Net.Cache.RequestCachePolicy(System.Net.Cache.RequestCacheLevel.NoCacheNoStore);req.Timeout=30000;var http=req as HttpWebRequest;if(http!=null)http.ReadWriteTimeout=30000;return req;}}
 static DownloadClient Client(){ServicePointManager.SecurityProtocol|=SecurityProtocolType.Tls12;var w=new DownloadClient();w.Headers[HttpRequestHeader.UserAgent]="HDR-Unlock/0.1";return w;}
 public static string Fetch(DlssBuild b,Action<string> progress,out DlssRelease release){
  progress("Cerco la release sul repository dell’autore…");using(var w=Client())release=PickRelease(w.DownloadString("https://api.github.com/repos/"+b.Repo+"/releases?per_page=10"),b);
  string dir=Path.Combine(Core.Data,"packages",b.Id,Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);string archive=Safe(dir,release.Asset);progress("Scarico "+release.Tag+" · "+release.Asset+"…");using(var w=Client())w.DownloadFile(release.Url,archive);
  string hash=Hash(archive);if(!String.IsNullOrEmpty(release.Digest)&&!String.Equals(release.Digest,"sha256:"+hash,StringComparison.OrdinalIgnoreCase))throw new Exception("SHA-256 diverso da quello pubblicato: pacchetto non utilizzato.");
  File.WriteAllText(Path.Combine(dir,"origine.txt"),release.Url+"\nSHA256 "+hash+"\n");progress("Verifico ed estraggo il pacchetto…");return Unpack(archive,Path.Combine(dir,"files"));
 }
 static string Tar(string args){var psi=new ProcessStartInfo(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"tar.exe"),args){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};using(var p=Process.Start(psi)){var err=p.StandardError.ReadToEndAsync();string text=p.StandardOutput.ReadToEnd();p.WaitForExit();if(p.ExitCode!=0)throw new Exception("Estrazione non riuscita: "+err.Result);return text;}}
 static string Q(string text){if(text.Contains("\""))throw new Exception("Percorso non valido");return "\""+text+"\"";}
 public static string Unpack(string archive,string root){
  Directory.CreateDirectory(root);if(Directory.GetFileSystemEntries(root).Length!=0)throw new Exception("La cartella di estrazione deve essere vuota.");
  string list=Tar("-tf "+Q(archive)),verbose=Tar("-tvf "+Q(archive));foreach(string line in verbose.Split('\n'))if(line.Length>0&&line[0]!='-'&&line[0]!='d'&&line.Trim().Length>0)throw new Exception("Archivio con collegamenti o elementi speciali non supportato.");
  var names=list.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries);if(names.Length>4000)throw new Exception("Pacchetto troppo grande.");foreach(string n in names){string clean=n.TrimEnd('/');if(clean.StartsWith("./"))clean=clean.Substring(2);if(clean.Length>0)Safe(root,clean);}
  Tar("-xf "+Q(archive)+" -C "+Q(root));var dlls=Directory.GetFiles(root,"OptiScaler.dll",SearchOption.AllDirectories);if(dlls.Length!=1)throw new Exception("L’archivio non contiene un unico OptiScaler.dll.");return Path.GetDirectoryName(dlls[0]);
 }
