 static DlssChange Change(string folder,string name,string source,byte[] bytes,bool delete=false){string dest=Safe(folder,name);return new DlssChange{Name=name,Source=source,SourceHash=source==null?null:Hash(source),Bytes=bytes,Delete=delete,Expected=File.Exists(dest)?Hash(dest):null};}
 public static DlssPlan Prepare(Game g,DlssOptions o,string package,string release){
  ActivityLog.Write("DLSS 5 · controllo loader, compatibilità e piano per "+g.Name);
  var scan=Inspect(g);if(scan.Blockers.Count>0)throw new Exception(String.Join("\n",scan.Blockers));string root=scan.Folder;
  var reshade=RenoDx.Loaders(root);if(reshade.Count>1)throw new Exception("Più loader ReShade: installazione fermata per evitare duplicati.");
  if(File.Exists(Safe(root,"ReShade64.dll"))&&!RenoDx.IsReShade(Safe(root,"ReShade64.dll")))throw new Exception("ReShade64.dll non riconosciuto: verifica il componente prima di collegarlo a OptiScaler.");
  string proxy=o.Proxy=="auto"?(scan.Proxy!=""?scan.Proxy:Proxies.FirstOrDefault(p=>!File.Exists(Safe(root,p)))):o.Proxy;
  if(proxy==null||!Proxies.Contains(proxy))throw new Exception("Nessun nome loader disponibile.");if(scan.Proxy!=""&&proxy!=scan.Proxy)throw new Exception("Conserva il loader già presente; cambia percorso solo dopo la rimozione.");if(File.Exists(Safe(root,proxy))&&!IsOpti(Safe(root,proxy)))throw new Exception(proxy+" appartiene a un altro componente e viene preservato.");
  var plan=new DlssPlan{Folder=root,Build=o.Build,Release=release,Summary=g.Name+"\nBuild: "+o.Build+" · "+release+"\nLoader: "+proxy+"\nNR "+(o.Enabled?"attivo":"spento")+" · modello "+o.Scale+"%\nGenerazione fotogrammi, HDR e altre mod: impostazioni conservate.\nInstallazione nei file; funzionamento in gioco da verificare."};
  var old=scan.Managed?ReadManifest(root):null;
  var manifest=old??new DlssManifest{Game=g.Id,Folder=root,PreviousOwner=scan.Owner,BackupRoot="dlss-backups/"+Guid.NewGuid().ToString("N")};manifest.Build=o.Build;manifest.Release=release;plan.Manifest=manifest;plan.MarkerExpected=File.Exists(Safe(root,Marker))?Hash(Safe(root,Marker)):null;
  if(!String.IsNullOrEmpty(package)){
   string main=Safe(package,"OptiScaler.dll");if(!Pe64(main)||!IsOpti(main)||!File.Exists(Safe(package,"OptiScaler.ini"))||!Directory.Exists(Safe(package,"OptiScaler")))throw new Exception("Seleziona il pacchetto completo x64: OptiScaler.dll, OptiScaler.ini e cartella OptiScaler.");
   foreach(string src in Directory.GetFiles(package,"*",SearchOption.AllDirectories)){
    string rel=src.Substring(Path.GetFullPath(package).TrimEnd('\\').Length+1).Replace('\\','/');Safe(package,rel);string ext=Path.GetExtension(rel).ToLowerInvariant();
    if(rel.Equals("OptiScaler.ini",StringComparison.OrdinalIgnoreCase))continue;
    bool allowed=rel.Equals("OptiScaler.dll",StringComparison.OrdinalIgnoreCase)||rel.Equals("nvngx.dll_dlssnr.dll",StringComparison.OrdinalIgnoreCase)||(rel.StartsWith("OptiScaler/",StringComparison.OrdinalIgnoreCase)&&new[]{".dll",".bin",".json",".ini",".hlsl",".cso"}.Contains(ext));
    if(!allowed||DlssLibraries.Names.Contains(Path.GetFileName(rel),StringComparer.OrdinalIgnoreCase))continue;string target=rel.Equals("OptiScaler.dll",StringComparison.OrdinalIgnoreCase)?proxy:rel;
    plan.Changes.Add(Change(root,target,src,null));
   }
  }else if(scan.Proxy=="")throw new Exception("Prima scarica una build o scegli il pacchetto estratto.");
  string runtime=String.IsNullOrEmpty(o.Runtime)?scan.Runtime:o.Runtime;if(o.Enabled&&!Pe64(runtime))throw new Exception("Manca nvngx_dlssnr.dll x64. Scegli il runtime NR adatto alla tua GPU oppure conserva quello già funzionante.");
  if(!String.IsNullOrEmpty(o.Runtime)&&!String.Equals(Path.GetFullPath(o.Runtime),scan.Runtime,StringComparison.OrdinalIgnoreCase))plan.Changes.Add(Change(root,"nvngx_dlssnr.dll",o.Runtime,null));
  FrameGeneration.Validate(g,o,package);
  string ini=scan.Ini;if(ini.Length==0&&package!=null)ini=File.ReadAllText(Safe(package,"OptiScaler.ini"));ini=Config(ini,o);if(reshade.Contains("ReShade64.dll"))ini=Core.Set(ini,"Plugins","LoadReshade","true");else if(reshade.Count==1)ini=Core.Set(ini,"Plugins","LoadReshade","false");
  plan.Changes.Add(Change(root,"OptiScaler.ini",null,new UTF8Encoding(false).GetBytes(ini)));
  if(o.FrameMode!="keep")plan.Summary+="\nFrame Generation: "+o.FrameMode+" · moltiplicatore richiesto "+o.FrameMultiplier+"×"+(o.AdaMfg?" · RTX 4000 sperimentale":"")+"\nLa configurazione non certifica il funzionamento in gioco. Riavvia dopo l’applicazione.";
  return plan;
 }
 public static DlssPlan PrepareUninstall(Game g,bool removeExternalBaseline=false){
  var s=Inspect(g);var plan=new DlssPlan{Folder=s.Folder,Uninstall=true,Summary=g.Name};
  if(s.Proxy==""&&!s.Managed&&!s.Autopilot)throw new Exception("OptiScaler non rilevato: non c’è un’installazione OptiScaler da rimuovere. ReShade e le mod MFG separate non vengono disinstallati da questo pulsante.");
  if(RenoDx.IsReShade(Safe(s.Folder,"ReShade64.dll"))&&Core.Get(s.Ini,"Plugins","LoadReshade")=="true")throw new Exception("ReShade dipende dal loader OptiScaler. Ripristina prima ReShade dalla sezione HDR, poi rimuovi OptiScaler, per non lasciare una catena incompleta.");
  if(s.Managed){var m=ReadManifest(s.Folder);foreach(var f in m.Files){string p=Safe(s.Folder,f.Name);if(!File.Exists(p)||Hash(p)!=f.After)throw new Exception("File cambiato da un’altra app: "+f.Name+". Ripristino fermato per non perdere modifiche successive.");string backup=f.Before==null?null:Safe(Core.Data,f.Backup);if(backup!=null&&(!File.Exists(backup)||Hash(backup)!=f.Before))throw new Exception("Backup mancante o modificato: "+f.Name);var restore=Change(s.Folder,f.Name,backup,null,backup==null);restore.RestoreAttributes=f.Attributes;plan.Changes.Add(restore);}plan.Changes.Add(Change(s.Folder,Marker,null,null,true));if(removeExternalBaseline){var restores=plan.Changes.ToDictionary(c=>c.Name,StringComparer.OrdinalIgnoreCase);Func<string,string> prior=n=>{Safe(s.Folder,n);DlssChange c;if(restores.TryGetValue(n,out c))return c.Delete?null:c.Source;string path=Safe(s.Folder,n);return File.Exists(path)?path:null;};if(prior("dlss5-autopilot.json")!=null){plan.Summary+="\nRimuove HDLSS e la precedente installazione OptiScaler di Autopilot in un’unica operazione.";return RemoveAutopilotBaseline(plan,prior);}}plan.Summary+="\nRipristina lo stato precedente a HDLSS: "+m.PreviousOwner+".\nSe era già installata una mod esterna, verrà ripristinata anch’essa.";return plan;}
  if(!s.Autopilot)throw new Exception("Installazione esterna senza registro supportato. Nessuna cancellazione alla cieca: usa il disinstallatore originale e Verifica integrità in Steam.");
  return RemoveAutopilotBaseline(plan,n=>{string path=Safe(s.Folder,n);return File.Exists(path)?path:null;});
 }
 static DlssPlan RemoveAutopilotBaseline(DlssPlan plan,Func<string,string> prior){
  Action<DlssChange> put=c=>{plan.Changes.RemoveAll(old=>String.Equals(old.Name,c.Name,StringComparison.OrdinalIgnoreCase));plan.Changes.Add(c);};
  var foreign=Core.Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(prior("dlss5-autopilot.json")));object mode;if(!foreign.TryGetValue("path",out mode)||Convert.ToString(mode)!="optiscaler")throw new Exception("Registro esterno non supportato per la rimozione completa.");object files;if(!foreign.TryGetValue("files",out files))throw new Exception("Elenco Autopilot mancante.");var list=((System.Collections.IEnumerable)files).Cast<object>().Select(Convert.ToString).Distinct(StringComparer.OrdinalIgnoreCase).ToList();if(list.Count>2000)throw new Exception("Registro troppo grande.");
  int restored=0,removed=0;foreach(string name in list){Safe(plan.Folder,name);if(BackupSuffixes.Any(x=>name.EndsWith(x,StringComparison.OrdinalIgnoreCase)))continue;
   string normalized=name.Replace('\\','/'),ext=Path.GetExtension(name).ToLowerInvariant();
   if(ext==".addon64"&&normalized.IndexOf("dlss",StringComparison.OrdinalIgnoreCase)<0)continue;
   if(normalized.StartsWith("ue4ss/",StringComparison.OrdinalIgnoreCase)||normalized.StartsWith("D3D12/",StringComparison.OrdinalIgnoreCase)||new[]{".exe",".pak",".ucas",".utoc",".sav"}.Contains(ext)||Path.GetFileName(name).Equals("Engine.ini",StringComparison.OrdinalIgnoreCase)||Path.GetFileName(name).Equals("GameUserSettings.ini",StringComparison.OrdinalIgnoreCase))throw new Exception("Il registro indica un file del gioco/mod estraneo: "+name);
   if(Proxies.Contains(name,StringComparer.OrdinalIgnoreCase)&&prior(name)!=null&&!IsOpti(prior(name)))throw new Exception("Il loader "+name+" non è più OptiScaler: niente rimozione automatica.");
   var backups=BackupSuffixes.Select(x=>name+x).Where(n=>prior(n)!=null).ToList();
   if(backups.Select(n=>Hash(prior(n))).Distinct().Count()>1)throw new Exception("Più backup diversi per "+name+". Non è possibile scegliere automaticamente l’originale.");
   string backup=backups.Count==0?null:prior(backups[0]);
   if(backup!=null){if(new FileInfo(backup).Length==0)throw new Exception("Backup vuoto: "+name);put(Change(plan.Folder,name,backup,null));foreach(string used in backups)put(Change(plan.Folder,used,null,null,true));restored++;}
   else if(prior(name)!=null){put(Change(plan.Folder,name,null,null,true));removed++;}
  }
  put(Change(plan.Folder,"dlss5-autopilot.json",null,null,true));plan.Summary+="\nRimuovi l’installazione registrata da DLSS Autopilot.\nBackup esterni recuperabili: "+restored+" · file da mettere da parte: "+removed+".\nUna copia di recupero viene creata prima di ogni modifica. I backup utilizzati vengono spostati nella copia di recupero. Gli originali non presenti nei backup NON sono ricostruibili: per certificarli usa Verifica integrità di Steam. ReShade/RenoDX/UE4SS non elencati restano invariati.";return plan;
 }
 static void Write(string path,byte[] bytes,int attrs){Directory.CreateDirectory(Path.GetDirectoryName(path));if(File.Exists(path))File.SetAttributes(path,FileAttributes.Normal);string temp=path+".hdr-unlock-"+Guid.NewGuid().ToString("N")+".tmp";File.WriteAllBytes(temp,bytes);if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);File.SetAttributes(path,(FileAttributes)attrs);}
 public static string Apply(Game g,DlssPlan plan){ActivityLog.Write((plan.Uninstall?"RIPRISTINO":"INSTALLAZIONE")+" · "+g.Name+" · "+plan.MarkerName);try{ActivityLog.Progress("Verifica dei componenti…");if(plan.HdrProfile!=null)plan.HdrProfile.Validate(g);string recovery=ApplyImpl(g,plan);if(plan.HdrProfile!=null){try{plan.HdrProfile.Commit(g,recovery);}catch{ApplyImpl(g,Recovery(g,Path.Combine(recovery,"transaction.json")));throw;}}ActivityLog.Progress("Operazione completata",100);return recovery;}catch(Exception ex){ActivityLog.Progress("Operazione interrotta · consulta il registro",100);ActivityLog.Write("ERRORE · "+ex.Message);throw;}}
 static string ApplyImpl(Game g,DlssPlan plan){
  Core.Closed(g);if(!String.Equals(plan.NativeSwap?Path.GetFullPath(g.Root):Path.GetDirectoryName(Path.GetFullPath(g.Exe)),plan.Folder,StringComparison.OrdinalIgnoreCase))throw new Exception("Il gioco selezionato è cambiato.");
  string tx=Path.Combine(Core.Data,"dlss-recovery",DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(tx);
  if(plan.Manifest!=null&&(File.Exists(Safe(plan.Folder,plan.MarkerName))?Hash(Safe(plan.Folder,plan.MarkerName)):null)!=plan.MarkerExpected)throw new Exception("Registro cambiato dopo l’anteprima: prepara di nuovo.");
  if(plan.Changes.Select(c=>c.Name).Distinct(StringComparer.OrdinalIgnoreCase).Count()!=plan.Changes.Count)throw new Exception("Percorsi duplicati nel piano.");
  ActivityLog.Write("Verifica percorsi, file correnti e hash delle sorgenti");var changes=new List<DlssChange>(plan.Changes);var before=new List<DlssFile>();var payload=new Dictionary<string,byte[]>();
  foreach(var c in changes){string path=Safe(plan.Folder,c.Name);if((File.Exists(path)?Hash(path):null)!=c.Expected)throw new Exception("File cambiato dopo l’anteprima: "+c.Name+". Prepara di nuovo.");if(!c.Delete){if(c.SourceHash!=null&&Hash(c.Source)!=c.SourceHash)throw new Exception("Sorgente cambiata dopo l’anteprima: "+c.Name);payload[c.Name]=c.Bytes??File.ReadAllBytes(c.Source);}}
  if(plan.Manifest!=null){var m=plan.Manifest;foreach(var c in changes){var entry=m.Files.FirstOrDefault(f=>String.Equals(f.Name,c.Name,StringComparison.OrdinalIgnoreCase));if(entry==null){entry=new DlssFile{Name=c.Name,Before=c.Expected,Attributes=File.Exists(Safe(plan.Folder,c.Name))?(int)File.GetAttributes(Safe(plan.Folder,c.Name)):(int)FileAttributes.Normal,Backup=m.BackupRoot+"/"+c.Name};m.Files.Add(entry);if(entry.Before!=null){string dst=Safe(Core.Data,entry.Backup);Directory.CreateDirectory(Path.GetDirectoryName(dst));if(File.Exists(dst)){if(Hash(dst)!=entry.Before)throw new Exception("Backup preesistente diverso: "+c.Name);}else File.Copy(Safe(plan.Folder,c.Name),dst,false);}}entry.After=BytesHash(payload[c.Name]);}
   var mc=Change(plan.Folder,plan.MarkerName,null,new UTF8Encoding(false).GetBytes(Core.Json.Serialize(m)));changes.Add(mc);payload[plan.MarkerName]=mc.Bytes;
  }
  foreach(var c in changes){string path=Safe(plan.Folder,c.Name);var f=new DlssFile{Name=c.Name,Before=c.Expected,After=c.Delete?null:BytesHash(payload[c.Name]),Attributes=File.Exists(path)?(int)File.GetAttributes(path):(int)FileAttributes.Normal,Backup=c.Name};before.Add(f);if(File.Exists(path)){string dst=Safe(tx,c.Name);Directory.CreateDirectory(Path.GetDirectoryName(dst));File.Copy(path,dst);}}
  ActivityLog.Progress("Backup dei file originali…");ActivityLog.Write("Backup e copia di recupero creati: "+tx);File.WriteAllText(Path.Combine(tx,"transaction.json"),Core.Json.Serialize(new DlssManifest{Folder=plan.Folder,Files=before}));File.WriteAllText(Path.Combine(tx,"state.txt"),"pending");var touched=new List<DlssFile>();
  try{int completed=0;foreach(var c in changes){ActivityLog.Progress("Applicazione dei file · "+completed+" / "+changes.Count,100.0*completed/Math.Max(1,changes.Count));string path=Safe(plan.Folder,c.Name);var f=before.First(x=>x.Name==c.Name);touched.Add(f);ActivityLog.Write((c.Delete?"Rimozione: ":"Scrittura: ")+c.Name);if(c.Delete){if(File.Exists(path)){File.SetAttributes(path,FileAttributes.Normal);File.Delete(path);}}else Write(path,payload[c.Name],c.RestoreAttributes??f.Attributes);if((File.Exists(path)?Hash(path):null)!=f.After)throw new Exception("Verifica fallita: "+c.Name);completed++;}File.WriteAllText(Path.Combine(tx,"state.txt"),"complete");ActivityLog.Write("Hash finali verificati · operazione completata");}
  catch(Exception ex){ActivityLog.Write("Errore di scrittura · annullamento delle modifiche");var errors=new List<string>();foreach(var f in touched.AsEnumerable().Reverse()){try{string path=Safe(plan.Folder,f.Name);if(f.Before==null){if(File.Exists(path)){File.SetAttributes(path,FileAttributes.Normal);File.Delete(path);}}else Write(path,File.ReadAllBytes(Safe(tx,f.Name)),f.Attributes);}catch(Exception err){errors.Add(err.Message);}}File.WriteAllText(Path.Combine(tx,"state.txt"),errors.Count==0?"rolled-back":"recovery-needed");throw new Exception(ex.Message+"\n"+(errors.Count==0?"Modifiche annullate.":"Recupero richiesto: "+String.Join("; ",errors))+"\nCopia di recupero: "+tx);}
  return tx;
 }
 public static DlssPlan Recovery(Game g,string transaction){string recoveryRoot=Path.GetFullPath(Path.Combine(Core.Data,"dlss-recovery"))+Path.DirectorySeparatorChar;string full=Path.GetFullPath(transaction);if(!full.StartsWith(recoveryRoot,StringComparison.OrdinalIgnoreCase)||Path.GetFileName(full)!="transaction.json")throw new Exception("Scegli un registro dalla cartella dlss-recovery di questa app.");var m=Core.Json.Deserialize<DlssManifest>(File.ReadAllText(full));if(m==null||m.Files==null)throw new Exception("Registro non valido.");var plan=new DlssPlan{Folder=m.Folder,NativeSwap=String.Equals(Path.GetFullPath(g.Root),m.Folder,StringComparison.OrdinalIgnoreCase),Uninstall=true,Summary="Annulla l’operazione usando la copia di recupero. Sono ripristinati solo i file elencati nel registro; gli altri restano invariati."};foreach(var f in m.Files){string dst=Safe(m.Folder,f.Name);if((File.Exists(dst)?Hash(dst):null)!=f.After)throw new Exception("File cambiato dopo l’operazione: "+f.Name);string backup=f.Before==null?null:Safe(Path.GetDirectoryName(full),f.Backup);if(backup!=null&&(!File.Exists(backup)||Hash(backup)!=f.Before))throw new Exception("Backup non valido: "+f.Name);var c=Change(m.Folder,f.Name,backup,null,backup==null);c.RestoreAttributes=f.Attributes;plan.Changes.Add(c);}return plan;}
 public static string Diagnose(Game g){var s=Inspect(g);var text=new StringBuilder(s.ToString());foreach(string name in new[]{"OptiScaler.log","ReShade.log"}){string p=Safe(s.Folder,name);if(!File.Exists(p))continue;text.AppendLine("\n"+name+" · "+File.GetLastWriteTime(p).ToString("g"));using(var stream=new FileStream(p,FileMode.Open,FileAccess.Read,FileShare.ReadWrite)){stream.Seek(Math.Max(0,stream.Length-160000),SeekOrigin.Begin);using(var r=new StreamReader(stream)){var lines=r.ReadToEnd().Split('\n').Where(l=>Regex.IsMatch(l,"dlssnr|neural|reshade|renodx|error|fail",RegexOptions.IgnoreCase)).Reverse().Take(22).Reverse();foreach(string l in lines)text.AppendLine(l.Trim());}}}text.AppendLine("\nEstratti diagnostici: un log vecchio o la sola presenza di una DLL non certificano DLSS 5 attivo.");return text.ToString();}
}
